import{_ as i,o,c as a,ag as l}from"./chunks/framework.BwSLX4ak.js";const b=JSON.parse('{"title":"BiliMusicBridge 常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"bilimusicbridge/troubleshooting.md","filePath":"bilimusicbridge/troubleshooting.md"}'),r={name:"bilimusicbridge/troubleshooting.md"};function c(t,e,s,d,u,n){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="bilimusicbridge-常见问题" tabindex="-1">BiliMusicBridge 常见问题 <a class="header-anchor" href="#bilimusicbridge-常见问题" aria-label="Permalink to &quot;BiliMusicBridge 常见问题&quot;">​</a></h1><h2 id="显示-allmusic-不可用" tabindex="-1">显示 AllMusic 不可用 <a class="header-anchor" href="#显示-allmusic-不可用" aria-label="Permalink to &quot;显示 AllMusic 不可用&quot;">​</a></h2><p>确认是 AllMusic 4.2.0 或更高版本，并与 BiliMusicBridge 安装在同一个实例。代理版 BiliMusicBridge 不会调用另一个 Bukkit 子服里的 AllMusic。检查 AllMusic 日志中音乐源是否加载成功，以及 <code>defaultApi</code> 是否等于对应音乐源 ID。</p><h2 id="弹幕来了但没有点歌" tabindex="-1">弹幕来了但没有点歌 <a class="header-anchor" href="#弹幕来了但没有点歌" aria-label="Permalink to &quot;弹幕来了但没有点歌&quot;">​</a></h2><p>检查 <code>room-id</code>、<code>song-request.prefixes</code> 和 <code>/bilimusic status</code>。默认前缀是“点歌”，消息需要以此前缀开头；空关键词或超出 <code>max-keyword-length</code> 的内容不会进入正常点歌流程。</p><p>默认单个 B 站账号冷却 20 秒，全局最小间隔 1000 毫秒，同一关键词 8 秒内去重，待处理队列容量为 100。修改这些值后执行 <code>/bilimusic reload</code>。如果默认配置没有向玩家广播失败原因，可以通过控制台日志查看拒绝原因，或按需开启 <code>messages.broadcast-failure</code>。</p><h2 id="提示没有玩家、重复歌曲或队列已满" tabindex="-1">提示没有玩家、重复歌曲或队列已满 <a class="header-anchor" href="#提示没有玩家、重复歌曲或队列已满" aria-label="Permalink to &quot;提示没有玩家、重复歌曲或队列已满&quot;">​</a></h2><p>默认 <code>allmusic.require-online-player: true</code>，需要在线且可播放音乐的玩家。插件保留 AllMusic 自己的队列长度、重复歌曲、歌曲黑名单与玩家点歌上限等检查。直播观众不是 Minecraft 账号，直接入队不会扣除 Vault 或代理经济。</p><h2 id="cookie-放在哪里" tabindex="-1">Cookie 放在哪里 <a class="header-anchor" href="#cookie-放在哪里" aria-label="Permalink to &quot;Cookie 放在哪里&quot;">​</a></h2><p>Cookie 为可选项。文件放在当前 BiliMusicBridge 插件的数据目录中，默认文件名 <code>cookie.json</code>；支持浏览器导出的数组、JSON 对象或原始 Cookie Header。路径必须在插件数据目录内。Cookie 与自动生成的 <code>device.properties</code> 属于运行数据，不应放进公开文档。</p><h2 id="搜索到了-但玩家听不到" tabindex="-1">搜索到了，但玩家听不到 <a class="header-anchor" href="#搜索到了-但玩家听不到" aria-label="Permalink to &quot;搜索到了，但玩家听不到&quot;">​</a></h2><p>先检查 AllMusic 客户端模组与服务端版本是否匹配，以及该音乐源是否能返回可用播放地址。BiliMusicBridge 负责接收弹幕、搜索和入队，实际解析与播放仍由 AllMusic 和音乐源完成。进一步排查见<a href="./../allmusic/troubleshooting.html">音乐源常见问题</a>。</p>',12)])])}const m=i(r,[["render",c]]);export{b as __pageData,m as default};
